using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ─── CalculateTotal with [DataRow] ───────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(25.00, 2, 0.10, 55.00, DisplayName = "Two items, 10% tax")]
    [DataRow(99.99, 3, 0.08, 323.97, DisplayName = "Three items, 8% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero price yields zero total")]
    [DataRow(50.00, 0, 0.15, 0.00, DisplayName = "Zero quantity yields zero total")]
    public void CalculateTotal_ValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, Math.Round(result, 2));
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative price throws")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity throws")]
    [DataRow(10.00, 1, -0.01, "taxRate", DisplayName = "Negative tax rate throws")]
    [DataRow(10.00, 1, 1.01, "taxRate", DisplayName = "Tax rate above 1 throws")]
    public void CalculateTotal_InvalidInputs_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // ─── ApplyDiscount with [DynamicData] ────────────────────────────────────

    public static IEnumerable<object[]> DiscountTestData =>
    [
        [100.00m, 0m, 100.00m],   // No discount
        [100.00m, 10m, 90.00m],   // 10% off
        [100.00m, 50m, 50.00m],   // 50% off
        [100.00m, 100m, 0.00m],   // Full discount
        [249.99m, 25m, 187.49m],  // 25% off non-round price
        [0.00m, 50m, 0.00m],     // Zero price stays zero
    ];

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_ValidInputs_ReturnsDiscountedPrice(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, Math.Round(result, 2));
    }

    public static IEnumerable<object[]> InvalidDiscountData =>
    [
        [-1m, "discountPercent"],
        [101m, "discountPercent"],
        [-0.01m, "discountPercent"],
    ];

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData))]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRange(
        decimal discountPercent, string expectedParamName)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, discountPercent));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // ─── FormatPrice with [DataRow] ──────────────────────────────────────────

    [TestMethod]
    [DataRow(19.99, "$", "$19.99", DisplayName = "Default dollar format")]
    [DataRow(1000.5, "€", "€1000.50", DisplayName = "Euro format")]
    [DataRow(0.0, "£", "£0.00", DisplayName = "Zero in pounds")]
    public void FormatPrice_ValidInputs_ReturnsFormattedString(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

